import{c as a,o as n,a1 as l,dq as e,dr as t,ds as i,dt as r,du as s,dv as o}from"./chunks/framework.zpcEI_VL.js";/* empty css                                                                            */const p=l('<h1 id="analys-och-nedbrytning-av-programutveckling-med-hjalp-av-verktyg-som-anvandningsfall" tabindex="-1">Analys och nedbrytning av programutveckling med hjälp av verktyg som <span class="a">användningsfall</span> <a class="header-anchor" href="#analys-och-nedbrytning-av-programutveckling-med-hjalp-av-verktyg-som-anvandningsfall" aria-label="Permalink to &quot;Analys och nedbrytning av programutveckling med hjälp av verktyg som &lt;span class=&quot;a&quot;&gt;användningsfall&lt;/span&gt;&quot;">​</a></h1><p>Inom programutveckling är det viktigt att ha en tydlig plan för vad programmet ska göra innan man börjar skriva kod. Ett av de vanligaste sätten att analysera och bryta ner ett program är att använda sig av <span class="a">användningsfall</span> och <span class="a">användningsfalldiagram</span>. Dessa hjälper till att tydliggöra hur olika användare kommer att interagera med programmet och vilka funktioner programmet behöver.</p><p>Det här avsnittet beskriver vad användningsfall och användningsfalldiagram är, hur de kan användas i utvecklingsprocessen och ger exempel som kan implementeras direkt i programmeringsuppgifter.</p><h2 id="anvandningsfall-vad-ar-det" tabindex="-1">Användningsfall, vad är det? <a class="header-anchor" href="#anvandningsfall-vad-ar-det" aria-label="Permalink to &quot;Användningsfall, vad är det?&quot;">​</a></h2><p>Ett <span class="a">användningsfall</span> beskriver ett specifikt scenario där en användare (kallas ofta &quot;aktör&quot;) interagerar med ett system för att nå ett mål. Användningsfall hjälper utvecklare att förstå vilka funktioner som behövs och hur de ska bete sig.</p><p>Ett <span class="a">användningsfall</span> är en beskrivning av hur en användare (kallas ofta &quot;<strong>aktör</strong>&quot;) interagerar med ett system för att uppnå ett mål. Ett användningsfall beskriver INTE hur systemet är uppbyggt tekniskt, utan fokuserar på vad användaren vill göra och vilka resultat som förväntas.</p><p>Viktiga delar i ett användningsfall:</p><ol><li><span class="a">Aktör</span>: Den person eller det system som interagerar med systemet.</li><li><span class="a">Mål</span>: Vad aktören vill uppnå.</li><li><span class="a">Huvudflöde</span>: En lista över steg som aktören och systemet tar för att nå målet.</li><li><span class="a">Alternativa flöden</span>: Vad som händer om något går fel eller om aktören väljer ett annat sätt att nå sitt mål.</li></ol><h3 id="exempel-pa-ett-anvandningsfall" tabindex="-1">Exempel på ett användningsfall <a class="header-anchor" href="#exempel-pa-ett-anvandningsfall" aria-label="Permalink to &quot;Exempel på ett användningsfall&quot;">​</a></h3><p>Tänk dig en <strong>bibliotekstjänst online</strong>. Ett användningsfall kan vara:</p><ol><li><strong>Mål</strong>: Låna en bok.</li><li><strong>Aktör</strong>: Bibliotekskund.</li><li><strong>Beskrivning av användningsfallet</strong>: <ul><li>Kunden loggar in på bibliotekets webbplats.</li><li>Kunden söker efter en bok.</li><li>Kunden väljer att låna boken.</li><li>Systemet bekräftar att boken är lånad och skickar en kvittens.</li></ul></li><li><strong>Alternativt flöde</strong>: <ul><li>Om lösenordet är fel, visar systemet ett felmeddelande och ber användaren att försöka igen.</li></ul></li></ol><p>Detta beskriver stegen som användaren och systemet går igenom för att uppnå målet.</p><br><h2 id="anvandningsfallsdiagram-vad-ar-det" tabindex="-1">Användningsfallsdiagram, vad är det? <a class="header-anchor" href="#anvandningsfallsdiagram-vad-ar-det" aria-label="Permalink to &quot;Användningsfallsdiagram, vad är det?&quot;">​</a></h2><p>Ett användningsfalldiagram <strong>är en grafisk representation (en ritning) av användningsfallen</strong> för ett system. <strong>Diagrammet visar aktörer, användningsfall och relationer mellan dessa</strong>. Diagrammen används ofta för att snabbt förstå hur systemet är uppbyggt och vilka funktioner det innehåller.</p><h3 id="nar-ska-anvandningsfalldiagram-anvandas" tabindex="-1">När ska användningsfalldiagram användas? <a class="header-anchor" href="#nar-ska-anvandningsfalldiagram-anvandas" aria-label="Permalink to &quot;När ska användningsfalldiagram användas?&quot;">​</a></h3><p>Användningsfalldiagram används:</p><ol><li>I början av ett projekt, när man planerar och designar ett system.</li><li>För att förstå kraven på ett system, vad det ska kunna göra.</li><li>När man vill visa hur olika användare interagerar med systemet.</li></ol><br><h3 id="komponenter-i-ett-anvandningsfalldiagram" tabindex="-1">Komponenter i ett användningsfalldiagram <a class="header-anchor" href="#komponenter-i-ett-anvandningsfalldiagram" aria-label="Permalink to &quot;Komponenter i ett användningsfalldiagram&quot;">​</a></h3><p>Ett användningsfalldiagram består av:</p><ol><li><span class="a">Aktörer</span>: De som använder systemet eller interagerar med det. <ul><li><strong>Symbol</strong>: En streckgubbe som representerar en användare.</li><li><strong>Exempel</strong>: En kund, en administratör, ett externt system.</li></ul></li><li><span class="a">Användningsfall</span>: Funktionerna i systemet. <ul><li><strong>Symbol</strong>: En oval som innehåller namnet på funktionen.</li><li><strong>Exempel</strong>: &quot;Logga in&quot;, &quot;Skicka meddelande&quot;, &quot;Boka biljett&quot;.</li></ul></li><li><span class="a">System</span>: Gränsen för det system som vi designar. <ul><li><strong>Symbol</strong>: En rektangel som omger användningsfallen.</li></ul></li><li><span class="a">Relationer</span>: <ul><li><strong>Association</strong>: Linjer som visar vilka aktörer som använder vilka funktioner.</li><li><strong>Generalization</strong>: Visar en &quot;är-en&quot;-relation, t.ex. om en aktör är en specialisering av en annan.</li><li><strong>Include</strong>: En funktion som alltid är en del av en annan funktion (visas med en streckad pil som pekar mot den inkluderade funktionen).</li><li><strong>Extend</strong>: En funktion som bara körs ibland (visas med en streckad pil mot huvudfunktionen).</li></ul></li></ol><br><h3 id="symboler-for-anvandningsfalldiagram" tabindex="-1">Symboler för användningsfalldiagram <a class="header-anchor" href="#symboler-for-anvandningsfalldiagram" aria-label="Permalink to &quot;Symboler för användningsfalldiagram&quot;">​</a></h3><p>Här är de vanliga symbolerna:</p><ol><li><span class="a">Streckgubbe</span>: Representerar en aktör.</li><li><span class="a">Oval</span>: Representerar ett <strong>användningsfall</strong> (funktion).</li><li><span class="a">Linje</span>: Visar samband mellan aktörer och användningsfall.</li><li><span class="a">Rektangel</span>: Representerar systemets gränser.</li><li><span class="a">Streckad pil</span>: Visar &quot;include&quot; eller &quot;extend&quot;-relationer.</li></ol><br><h3 id="exempel-pa-anvandningsfalldiagram" tabindex="-1">Exempel på användningsfalldiagram <a class="header-anchor" href="#exempel-pa-anvandningsfalldiagram" aria-label="Permalink to &quot;Exempel på användningsfalldiagram&quot;">​</a></h3><br><h4 id="exempel-1-bokningssystem-for-biobiljetter" tabindex="-1"><span class="a">Exempel 1: Bokningssystem för biobiljetter</span> <a class="header-anchor" href="#exempel-1-bokningssystem-for-biobiljetter" aria-label="Permalink to &quot;&lt;span class=&quot;a&quot;&gt;Exempel 1: Bokningssystem för biobiljetter&lt;/span&gt;&quot;">​</a></h4><ul><li><p>Aktörer:</p><ul><li>Kund</li><li>Administratör</li></ul></li><li><p>Användningsfall:</p><ul><li>Söka efter film</li><li>Boka biljett</li><li>Avboka biljett</li><li>Skapa rapport (admin)</li></ul></li><li><p>Diagram:</p><ul><li>Kunden (streckgubben) kopplas med linjer till &quot;Söka efter film&quot;, &quot;Boka biljett&quot; och &quot;Avboka biljett&quot;.</li><li>Administratören kopplas till &quot;Skapa rapport&quot;.</li></ul><p><img src="'+e+'" alt=""></p></li></ul><br><br><h4 id="exempel-2-bankapp" tabindex="-1"><span class="a">Exempel 2: Bankapp</span> <a class="header-anchor" href="#exempel-2-bankapp" aria-label="Permalink to &quot;&lt;span class=&quot;a&quot;&gt;Exempel 2: Bankapp&lt;/span&gt;&quot;">​</a></h4><ul><li><p>Aktörer:</p><ul><li>Bankkund</li><li>Banktjänsteman</li></ul></li><li><p>Användningsfall:</p><ul><li>Logga in</li><li>Se saldo</li><li>Göra överföring</li><li>Skapa konto</li></ul></li><li><p>Diagram:</p><ul><li>Kunden (streckgubben) kopplas med linjer till &quot;Logga in&quot;, &quot;Se saldo&quot; och &quot;Göra överföringar&quot;.</li><li>Banktjänsteman kopplas till &quot;Skapa konto&quot;.</li><li>&quot;Logga in&quot; inkluderar &quot;Verifiera identitet&quot;.</li></ul><p><img src="'+t+'" alt=""></p></li></ul><br><br><h4 id="exempel-3-online-shopping-system" tabindex="-1"><span class="a">Exempel 3: Online Shopping System </span> <a class="header-anchor" href="#exempel-3-online-shopping-system" aria-label="Permalink to &quot;&lt;span class=&quot;a&quot;&gt;Exempel 3: Online Shopping System &lt;/span&gt;&quot;">​</a></h4><ul><li><p>Aktörer:</p><ul><li>Kund</li><li>Administratör</li><li>Betalningssystem (externt system)</li></ul></li><li><p>Användningsfall:</p><ul><li>Söka efter produkt</li><li>Lägga produkt i varukorg</li><li>Göra betalning (kopplas till externt betalningssystem)</li><li>Spåra leverans</li><li>Hantera produkter (administratör)</li><li>Generera försäljningsrapport (administratör)</li></ul></li><li><p>Diagram:</p><ul><li>Kunden (streckgubben) kopplas med linjer till &quot;Söka efter produkt&quot;, &quot;Lägga produkt i varukorg&quot;, &quot;Göra betalning&quot; och &quot;Spåra leverans&quot;.</li><li>Administratören kopplas till &quot;Hantera produkter&quot; och &quot;Generera försäljningsrapport&quot;.</li><li>&quot;Göra betalning&quot; har en relation till det externa &quot;Betalningssystemet&quot;.</li></ul><p><img src="'+i+'" alt=""></p></li></ul><br><br><h4 id="exempel-4-bibliotekshanteringssystem" tabindex="-1"><span class="a">Exempel 4: Bibliotekshanteringssystem </span> <a class="header-anchor" href="#exempel-4-bibliotekshanteringssystem" aria-label="Permalink to &quot;&lt;span class=&quot;a&quot;&gt;Exempel 4: Bibliotekshanteringssystem &lt;/span&gt;&quot;">​</a></h4><ul><li>Aktörer: <ul><li>Medlem</li><li>Bibliotekarie</li></ul></li><li>Användningsfall: <ul><li>Söka efter bok</li><li>Låna bok</li><li>Lämna tillbaka bok</li><li>Betala förseningsavgift</li><li>Lägga till/ta bort bok (bibliotekarie)</li><li>Generera rapport (bibliotekarie)</li></ul></li><li>Diagram: <ul><li><p>Medlem kopplas till &quot;Söka efter bok&quot;, &quot;Låna bok&quot;, &quot;Lämna tillbaka bok&quot; och &quot;Betala förseningsavgift&quot;.</p></li><li><p>Bibliotekarie kopplas till &quot;Lägga till/ta bort bok&quot; och &quot;Generera rapport&quot;.</p></li><li><p>&quot;Låna bok&quot; inkluderar &quot;Kontrollera tillgänglighet&quot;.</p></li><li><p>&quot;Lämna tillbaka bok&quot; inkluderar &quot;Uppdatera register&quot; och förlängs (extend) med &quot;Betala förseningsavgift&quot;.</p><p><img src="'+r+'" alt=""></p></li></ul></li></ul><br><br><h4 id="exempel-5-sjukhushanteringssystem" tabindex="-1"><span class="a">Exempel 5: Sjukhushanteringssystem </span> <a class="header-anchor" href="#exempel-5-sjukhushanteringssystem" aria-label="Permalink to &quot;&lt;span class=&quot;a&quot;&gt;Exempel 5: Sjukhushanteringssystem &lt;/span&gt;&quot;">​</a></h4><ul><li>Aktörer: <ul><li>Patient</li><li>Läkare</li><li>Sjuksköterska</li></ul></li><li>Användningsfall: <ul><li>Boka läkarbesök</li><li>Registrera patientuppgifter</li><li>Föreskriva medicin (läkare)</li><li>Skapa patientrapport (läkare och sjuksköterska)</li><li>Administrera betalning</li></ul></li><li>Diagram: <ul><li><p>Patient kopplas till &quot;Boka läkarbesök&quot; och &quot;Administrera betalning&quot;.</p></li><li><p>Läkare kopplas till &quot;Föreskriva medicin&quot; och &quot;Skapa patientrapport&quot;.</p></li><li><p>Sjuksköterska kopplas till &quot;Skapa patientrapport&quot;.</p></li><li><p>&quot;Boka läkarbesök&quot; inkluderar &quot;Registrera patientuppgifter&quot;.</p><p><img src="'+s+'" alt=""></p></li></ul></li></ul><br><br><h4 id="exempel-6-matleveransapp" tabindex="-1"><span class="a">Exempel 6: Matleveransapp</span> <a class="header-anchor" href="#exempel-6-matleveransapp" aria-label="Permalink to &quot;&lt;span class=&quot;a&quot;&gt;Exempel 6: Matleveransapp&lt;/span&gt;&quot;">​</a></h4><ul><li>Aktörer: <ul><li>Kund</li><li>restaurang</li><li>Leveransförare</li></ul></li><li>Användningsfall: <ul><li>Beställa mat</li><li>Betala för beställning</li><li>Uppdatera meny (restaurang)</li><li>Leverera beställning (leveransförare)</li><li>Spåra leverans (kund)</li></ul></li><li>Diagram: <ul><li><p>Kunden kopplas till &quot;Beställa mat&quot;, &quot;Betala för beställning&quot; och &quot;Spåra leverans&quot;.</p></li><li><p>Restaurangen kopplas till &quot;Uppdatera meny&quot;.</p></li><li><p>Leveransföraren kopplas till &quot;Leverera beställning&quot;.</p></li><li><p>&quot;Beställa mat&quot; inkluderar &quot;Kontrollera lagerstatus&quot;.</p><p><img src="'+o+'" alt=""></p></li></ul></li></ul><br><h2 id="avslutning" tabindex="-1">Avslutning <a class="header-anchor" href="#avslutning" aria-label="Permalink to &quot;Avslutning&quot;">​</a></h2><p><strong>Användningsfall</strong> och <strong>användningsfalldiagram</strong> är kraftfulla verktyg för att <strong>analysera och bryta ner problem</strong> inom programutveckling. De hjälper till att skapa struktur och tydlighet i processen, samtidigt som de ökar chansen att slutanvändaren får ett system som motsvarar deras förväntningar.</p><p>För gymnasiestudenter i Programmering 2 ger detta en bra grund för att strukturera sina projekt och skapa effektiva program. Genom att förstå och tillämpa dessa verktyg kan ni bli bättre på att planera och genomföra era programmeringsprojekt. Det gör inte bara utvecklingsprocessen enklare, utan leder också till bättre resultat och en mer professionell arbetsmetodik.</p>',55),g=[p],f=JSON.parse('{"title":"Analys och nedbrytning av programutveckling med hjälp av verktyg som användningsfall","description":"","frontmatter":{"outline":[1,6]},"headers":[],"relativePath":"programming2/part16/index.md","filePath":"programming2/part16/index.md"}'),u={name:"programming2/part16/index.md"},h=Object.assign(u,{setup(d){return(m,k)=>(n(),a("div",null,g))}});export{f as __pageData,h as default};
